                    s1 = wasm_f64x2_add(s1, wasm_f64x2_mul(vi, wasm_v128_load(row + 2)));
                    s2 = wasm_f64x2_add(s2, wasm_f64x2_mul(vi, wasm_v128_load(row + 4)));
