        int left = GOV_FREE_DET ? 1000 : (int)((GOV_B - gov_used - (lc_active && !lc_applied ? NS_RESERVE : 0)) / GC_CELL);
        gov_cells = left < 0 ? 0 : left > DET_BUDGET ? DET_BUDGET : left;
        gov_ncell = 0;
        detect(cur);
        gov_used += gov_ncell * GC_CELL;
